namespace EnterpriseKnowledgeAgent.Shared.Chat;

/// <summary>
/// Author of a single <c>ConversationMessage</c> in a knowledge-base chat
/// (Module CHAT). A conversation is an alternating sequence of
/// <see cref="User"/> questions and <see cref="Assistant"/> answers.
/// </summary>
public enum MessageRole
{
    /// <summary>A question typed by the end user.</summary>
    User,

    /// <summary>A knowledge-base-grounded answer generated by the platform.</summary>
    Assistant,
}
